<div class="table-scroll"><table><thead><tr><th>Date</th><th>Student</th><th>Problem Type</th><th>Work Status</th><th>Completion</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['support_date'])?></td><td><strong><?=e($r['student_name'])?></strong><div class="muted small"><?=e($r['student_number'])?></div></td><td><?=e($r['problem_type'])?></td><td><?=status_pill($r['work_status'])?></td><td><?=e($r['completion_date']??'—')?></td><td class="table-actions"><a href="<?=url('support',['id'=>$r['id']])?>">View</a><a href="<?=url('support-form',['id'=>$r['id']])?>">Edit</a></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty">No support records yet. Create a support record to get started.</div><?php endif;?></div>
